// shared/utils/MathUtils.js
import * as THREE from 'three';

export const MathUtils = {
    // AABB Collision Detection
    checkAABB(box1, box2) {
        return (box1.min.x <= box2.max.x && box1.max.x >= box2.min.x &&
                box1.min.y <= box2.max.y && box1.max.y >= box2.min.y &&
                box1.min.z <= box2.max.z && box1.max.z >= box2.min.z);
    },

    // Generate a random number between min and max
    randomRange(min, max) {
        return Math.random() * (max - min) + min;
    },

    // Clamp value between min and max
    clamp(value, min, max) {
        return Math.max(min, Math.min(max, value));
    },

    // Sine wave displacement for procedural geometry
    sineDisplacement(position, time, frequency = 1.0, amplitude = 0.1) {
        const x = position.x;
        const y = position.y;
        const z = position.z;
        return Math.sin(x * frequency + time) * amplitude + 
               Math.cos(y * frequency + time) * amplitude;
    },

    // Linear interpolation
    lerp(start, end, t) {
        return start * (1 - t) + end * t;
    },

    // Convert degrees to radians
    degToRad(degrees) {
        return degrees * (Math.PI / 180);
    }
};
