// shared/vfx/CameraShake.js
export class CameraShake {
    constructor(camera) {
        this.camera = camera;
        this.intensity = 0;
        this.decayRate = 0.95;
        this.isShaking = false;
    }

    shake(magnitude) {
        this.intensity = Math.max(this.intensity, magnitude);
        this.isShaking = true;
    }

    update(deltaTime) {
        if (!this.isShaking || this.intensity <= 0.01) {
            this.intensity = 0;
            this.isShaking = false;
            // Reset camera position to original
            this.camera.position.x += (this.camera.__originalX || this.camera.position.x) - this.camera.position.x;
            this.camera.position.y += (this.camera.__originalY || this.camera.position.y) - this.camera.position.y;
            this.camera.position.z += (this.camera.__originalZ || this.camera.position.z) - this.camera.position.z;
            return;
        }

        // Apply shake offset
        const offsetX = (Math.random() - 0.5) * this.intensity;
        const offsetY = (Math.random() - 0.5) * this.intensity;
        const offsetZ = (Math.random() - 0.5) * this.intensity * 0.5;

        // Store original position if not already stored
        if (!this.camera.__originalX) {
            this.camera.__originalX = this.camera.position.x;
            this.camera.__originalY = this.camera.position.y;
            this.camera.__originalZ = this.camera.position.z;
        }

        this.camera.position.x = this.camera.__originalX + offsetX;
        this.camera.position.y = this.camera.__originalY + offsetY;
        this.camera.position.z = this.camera.__originalZ + offsetZ;

        // Decay intensity
        this.intensity *= this.decayRate;

        if (this.intensity <= 0.01) {
            this.intensity = 0;
            this.isShaking = false;
        }
    }

    reset() {
        this.intensity = 0;
        this.isShaking = false;
        if (this.camera.__originalX !== undefined) {
            this.camera.position.x = this.camera.__originalX;
            this.camera.position.y = this.camera.__originalY;
            this.camera.position.z = this.camera.__originalZ;
        }
        delete this.camera.__originalX;
        delete this.camera.__originalY;
        delete this.camera.__originalZ;
    }
}
